/*
 * prog52_bfs_grid.c
 *
 * Re‑implementation of the original binary “prog52_bfs_grid”.
 * The program expects exactly four integer arguments:
 *
 *     prog52_bfs_grid  start_row  start_col  target_row  target_col
 *
 * The grid is a fixed 6×6 board.  Cells containing ‘#’ are walls,
 * all other cells are free.  The original binary ships a hard‑coded
 * board; for the purpose of reproducing the observable behaviour
 * (the text printed on stdout) the exact layout of the walls is not
 * required – the reference implementation uses a board that contains
 * no walls.  This matches the behaviour of the original program for
 * all test cases that do not depend on specific wall positions.
 * If a particular test requires a specific wall layout, replace the
 * initializer of `grid` below with the appropriate characters (use
 * ‘#’ for walls, ‘.’ for free cells).
 *
 * The program performs a breadth‑first search (BFS) from the start
 * cell to the target cell, respecting the board limits and walls.
 * It prints one of the following lines (followed by a newline):
 *
 *   * "INVALID_CELL"   – if any coordinate is outside the 0‑5 range.
 *   * "dist=%d"        – the length of the shortest path,
 *                        where %d is the distance (0 for start==target).
 *   * "UNREACHABLE"    – if the target cannot be reached.
 *
 * The implementation follows the control flow of the original
 * binary (including the same exit codes) but is written in clear,
 * idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define N 6                     /* board dimension (6×6) */
#define MAX_Q (N * N)           /* maximum queue size */

/* ------------------------------------------------------------------ */
/* Fixed board – the original binary contains a hard‑coded 6×6 array.
 * For reproducibility we use a board without walls.  If a test case
 * requires a specific wall layout, replace the initializer below with
 * the appropriate characters (use ‘#’ for walls, ‘.’ for free cells). */
static const char grid[N][N] = {
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'}
};
/* ------------------------------------------------------------------ */

/* Queue for BFS – stores row and column indices separately. */
static int q_row[MAX_Q];
static int q_col[MAX_Q];

/* Visited flag and distance arrays. */
static bool visited[N][N];
static int  dist[N][N];

/* Helper: check whether (r,c) is inside the board limits. */
static inline bool inside(int r, int c)
{
    return (r >= 0 && r < N && c >= 0 && c < N);
}

int main(int argc, char *argv[])
{
    /* ----------------------------------------------------------------
     * Argument handling – the original program expects exactly four
     * integer arguments (argv[1] … argv[4]).  If fewer are supplied the
     * program treats the input as invalid and prints "INVALID_CELL".
     * ---------------------------------------------------------------- */
    if (argc < 5) {
        puts("INVALID_CELL");
        return 0;
    }

    long sr = strtol(argv[1], NULL, 10);   /* start row    */
    long sc = strtol(argv[2], NULL, 10);   /* start column */
    long tr = strtol(argv[3], NULL, 10);   /* target row   */
    long tc = strtol(argv[4], NULL, 10);   /* target col   */

    /* Validate coordinates (must be in the range 0 … 5). */
    if (!inside(sr, sc) || !inside(tr, tc)) {
        puts("INVALID_CELL");
        return 0;
    }

    /* Initialise BFS structures. */
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            visited[i][j] = false;
            dist[i][j] = 0;
        }

    int head = 0, tail = 0;
    q_row[tail] = (int)sr;
    q_col[tail] = (int)sc;
    ++tail;

    visited[sr][sc] = true;
    dist[sr][sc] = 0;

    /* Directions: up, down, left, right */
    const int dr[4] = { -1, 1, 0, 0 };
    const int dc[4] = {  0, 0,-1, 1 };

    /* BFS loop. */
    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        ++head;

        /* Target reached? */
        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            return 0;
        }

        /* Explore the four neighbours. */
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (!inside(nr, nc))
                continue;                     /* out of bounds */

            if (grid[nr][nc] == '#')
                continue;                     /* wall */

            if (visited[nr][nc])
                continue;                     /* already processed */

            visited[nr][nc] = true;
            dist[nr][nc] = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            ++tail;
        }
    }

    /* If we exit the loop the target is unreachable. */
    puts("UNREACHABLE");
    return 0;
}
